sys_script.script:
(function executeRule(current, previous /*null when async*/) {

	//calculate years since date, returns int
	function calculateYear(date){
		if(!date){
			return null;
		}
		var glideDate = new GlideDateTime(date);
		var today = new GlideDateTime();

		var age = today.getYearUTC() - glideDate.getYearUTC();
		if(today.getMonthUTC() < glideDate.getMonthUTC() || (today.getMonthUTC() == glideDate.getMonthUTC() && today.getDayOfMonthUTC() < glideDate.getDayOfMonthUTC())){
			age--;
		}
		return age;
	}

	var subjectPerson = current.getValue('subject_person');
	if (subjectPerson && !(subjectPerson.trim() === '')) {
	    var userRecord = new GlideRecord('sys_user');
	    userRecord.get(subjectPerson);

		var gender = userRecord.gender;
		current.setValue('employee_gender', gender);


		//reset values - if subject person changes but doesn't have a HR profile reference
		current.setValue('emp_age', '');
		current.setValue('emp_time_in_pos', '');


		var hrReference = userRecord.x_hccc_base_hr_profile;
		if (hrReference && !(hrReference.trim() === '')) {
			var hrProfile = new GlideRecord('sn_hr_core_profile');
			hrProfile.get(hrReference);

			var birthDate = hrProfile.date_of_birth;
			current.setValue('emp_age', calculateYear(birthDate));

			var jobRecord = new GlideRecord('sn_hr_core_job');
			jobRecord.addQuery('job_active', true);
			jobRecord.addQuery('user', subjectPerson);
			jobRecord.query();

			if(jobRecord.next()){
				current.setValue('emp_time_in_pos', calculateYear(jobRecord.job_start_date).toString());
			}
		}
	}

})(current, previous);
